"""Golden cases for the agent-knowledge Rust port, generated by the PYTHON reference implementation.

    env -i PATH=/usr/bin:/bin HOME=/home/golden LANG=C.UTF-8 TMPDIR=$(mktemp -d) \
        "$PYREL/knowledge/.venv/bin/python" -I backend/crates/agent-knowledge/tests/gen/gen_goldens.py backend/crates/agent-knowledge/tests/golden
    (from the repo root; PYREL=$(node backend/parity/lib/python-release.mjs) is the last Python backend, see
     backend/parity/lib/python-release.mjs)

Writes:
  json_loads.json   CPython 3.13 json.loads(bytes): repr of the value, or the JSONDecodeError (pos, msg), or the
                    exception class (UnicodeDecodeError, ValueError for >4300-digit ints)
  bodies.json       FastAPI 0.141 + pydantic 2.13 through the real app: (route, raw body, content type) -> the 422/400
                    problem (status, code, detail), or "valid" when validation passed
  config.json       load_config(): str(ValidationError) / the error text, or selected fields
Hermetic: temp dirs only, MemoryStore + HashEmbedder, no network.
"""
from __future__ import annotations

import asyncio
import json
import os
import sys
import tempfile
from pathlib import Path

import httpx

from agent_knowledge.app import create_app
from agent_knowledge.config import Config, load_config
from agent_knowledge.embed import HashEmbedder
from agent_knowledge.stores.memory import MemoryStore

OUT = Path(sys.argv[1])


def has_surrogate(v: object) -> bool:
    if isinstance(v, str):
        return any(0xD800 <= ord(c) <= 0xDFFF for c in v)
    if isinstance(v, list):
        return any(has_surrogate(x) for x in v)
    if isinstance(v, dict):
        return any(has_surrogate(k) or has_surrogate(x) for k, x in v.items())
    return False


def json_cases() -> list[bytes]:
    s = [
        "", " ", "{}", "[]", '{"a":1}', ' {"a" : [1, 2.5, "x", null, true, false]} ', "0", "-0", "1.5", "1e5", "1E+2",
        "-1.5e-3", "12345678901234567890", "-9223372036854775809", "9223372036854775807", "1" * 4300, "1" * 4301,
        "-" + "1" * 4300, "1.0", ".5", "01", "-", "--1", "1.", "1e", "1e+", "1.e5", "1e400", "-1e400", "NaN",
        "Infinity", "-Infinity", "-NaN", "nul", "null", "true", "tru", "falsey", '"\\u00e9"', '"\\ud83d\\ude00"',
        '"\\ud83d"', '"\\ud83dx"', '"\\ud83d\\u0041"', '"\\ud83d\\u12"', '"\\x"', '"\\u12"', '"\\u12G4"',
        '"\\u0041', '"abc', '"a\nb"', '"a\tb"', '"a\x1fb"', '"\\', '"\\"', "[1,]", "[1, ]", '{"a":1,}',
        '{"a":1 , }', '{"a" 1}', "{1:2}", '{"a":}', "[1 2]", '{"a":1 "b":2}', '{"a":1,"a":2,"b":3}', "[", "{",
        '{"a"', '{"a":', '{"a":1', "[1", "[1,", "[\n1\t,\r2 ]", "1 x", "  1  ", '"\\/\\b\\f\\n\\r\\t\\"\\\\"',
        '{"":0}', "[[[[]]]]", '{"a":{"b":{"c":[{}]}}}', "﻿{}", "[1e-7, 5e-324, 1.7976931348623157e308]",
        '"é中\U0001F600"', '[0.1, 100.0, 1e16, 1e15]', "{,}", "[,]", ",", "]", "}", '"', "tRue",
    ]
    out = [x.encode("utf-8") for x in s]
    out += [
        b"\xef\xbb\xbf{}", "{}".encode("utf-16"), "{}".encode("utf-16-le"), "{}".encode("utf-16-be"),
        '{"a":1}'.encode("utf-32"), '{"a":1}'.encode("utf-32-le"), '{"a":1}'.encode("utf-32-be"), b"\xff",
        b'"\xed\xa0\x80"', b'"\xc3"', b'{"a":"\xe9"}', b"\x00\x00", b"[1]\x00", "[1]".encode("utf-16")[:-1],
        b'"\xf4\x90\x80\x80"', b'"\xe0\x80\x80"',
    ]
    return out


def gen_json() -> list[dict[str, object]]:
    cases = []
    for b in json_cases():
        rec: dict[str, object] = {"hex": b.hex()}
        try:
            v = json.loads(b)
        except json.JSONDecodeError as e:
            rec.update(err="JSONDecodeError", pos=e.pos, msg=e.msg)
        except Exception as e:  # noqa: BLE001
            rec.update(err=type(e).__name__)
        else:
            rec.update(repr=repr(v), surrogate=has_surrogate(v))
        cases.append(rec)
    return cases


