async def gen_bodies(tmp: Path) -> list[dict[str, object]]:
    # a high rate limit: one admin sends every case (the default 120/min would turn the tail into 429s)
    cfg = Config(data_dir=tmp / "data", router_url="http://127.0.0.1:9", default_rate_per_min=100_000)
    app = create_app(cfg, stores={"lancedb": MemoryStore(), "qdrant": MemoryStore()}, embedder=HashEmbedder(32))
    admin = (cfg.data_dir / "admin.key").read_text().strip()
    out = []
    async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://127.0.0.1:8795") as c:
        for endpoint, method, path in BODY_ROUTES:
            cases: list[tuple[object, str]] = list(COMMON) + [(json.dumps(b), "application/json") for b in PER_ROUTE[endpoint]]
            for raw, ctype in cases:
                body = b"" if raw is None else (raw.encode("latin-1") if raw == "\xff" else str(raw).encode())
                headers = {"Host": "127.0.0.1:8795", "Authorization": f"Bearer {admin}"}
                if ctype:
                    headers["Content-Type"] = ctype
                r = await c.request(method, path, content=body, headers=headers)
                rec: dict[str, object] = {"endpoint": endpoint, "method": method, "path": path, "body_hex": body.hex(),
                                          "ctype": ctype}
                j = r.json() if r.headers.get("content-type", "").startswith("application/problem+json") else {}
                if j.get("code") in ("validation_error", "http_error"):
                    rec.update(status=r.status_code, code=j["code"], detail=j["detail"])
                else:
                    assert r.status_code != 429, (endpoint, raw)
                    rec.update(status="valid", http_status=r.status_code)
                out.append(rec)
    return out


